document.addEventListener("click",e=>{const b=e.target.closest("#kwcat .pick");if(!b)return;e.preventDefault();
 if(b.dataset.gen){const c=b.dataset.gen;KF.gens=KF.gens.includes(c)?KF.gens.filter(x=>x!==c):[...KF.gens,c]}
 else if(b.dataset.uv){const c=b.dataset.uv;KF.uitv=KF.uitv.includes(c)?KF.uitv.filter(x=>x!==c):[...KF.uitv,c]}
 else if(b.dataset.opt){const c=b.dataset.opt,n={"":"verplicht",verplicht:"gewenst",gewenst:""}[KF.opt[c]||""];if(n)KF.opt[c]=n;else delete KF.opt[c]}
 kwCat()},true);

let HL=null;fetch("health.json?"+Date.now()).then(r=>r.json()).then(j=>{HL=j;const d=$("#datum");if(d&&j.status!=="ok")d.insertAdjacentHTML("beforeend",` <a href="#uitleg" class="sdot ${j.status}" title="Systeemstatus: ${j.status}">●</a>`);if(seg===8)statusBox()}).catch(()=>{});
function statusBox(){const c=$("#cards");if(!c||seg!==8||$("#sbox"))return;const h=HL;
 const lbl={ok:"Alles werkt",waarschuwing:"Werkt, met waarschuwing",fout:"Probleem"};
 c.insertAdjacentHTML("afterbegin",`<article class="card wide" id="sbox"><div class="body"><h2 class="t">Systeemstatus ${h?`<span class="chip ${h.status==="ok"?"ok":h.status==="fout"?"bad":"warn"}">${lbl[h.status]||h.status}</span>`:""}</h2>
 ${h?`<div class="meta">Gecontroleerd ${esc(h.tijd)}</div><ul class="ul">${h.checks.map(x=>`<li>${x.ok?"✅":x.ernst==="fout"?"❌":"⚠️"} <b>${esc(x.naam)}</b>: ${esc(x.detail)}</li>`).join("")}</ul>`:'<div class="meta">Nog geen statuscheck beschikbaar.</div>'}</div></article>`)}

