function norm(j){(j.segmenten||[]).forEach(s=>{s.deals=(s.deals||[]).filter(d=>d&&d.autos&&d.autos.length);s.deals.forEach(d=>{d.rdw=Object.assign({model:"",d7:"?",d30:"?",m6:"?",trend:""},d.rdw||{});d.marge=Object.assign({verkoop:0,kosten:0,marge:0,pct:0,bod:0,bericht:"",bpm:""},d.marge||{});d.reden=d.reden||"";d.groep=d.groep||"";d.merk=d.merk||"";
 d.autos.forEach(a=>{a.opties=a.opties||[];a.vlaggen=a.vlaggen||[];a.contact=a.contact||{};a.historie=a.historie||[];a.titel=a.titel||"";a.bron=a.bron||""})})});return j}

