function ookop(c){const L=c.ook_op||[];if(!L.length)return"";const all=[{bron:c.bron,url:c.url,prijs:c.prijs},...L].sort((a,b)=>(a.prijs||9e9)-(b.prijs||9e9));const diff=all.some(x=>x.prijs&&Math.abs(x.prijs-all[0].prijs)>0.5);
return `<div class="ookop"><b>Zelfde auto op ${all.length} platforms</b>${diff?` <span class="chip warn">prijsverschil ${eur(all[all.length-1].prijs-all[0].prijs)}</span>`:""}<div>${all.map((x,i)=>`<a href="${esc(x.url)}" target="_blank" rel="noopener" class="${diff&&i===0?"goedkoopst":""}">${esc(x.bron||"link")}${diff?" "+eur(x.prijs):""}${diff&&i===0?" (goedkoopst)":""}</a>`).join(" · ")}</div></div>`}
